 '.cert .rs{font-size:13.5pt;line-height:1.7;margin:0;max-width:200mm}.cert .rs b{color:var(--c)}'+
 '.cert .sgs{width:100%;display:grid;grid-template-columns:1fr 26mm 1fr;align-items:end;padding-bottom:1mm}.cert .bcs{width:24mm;height:24mm;justify-self:center}.cert .cs{display:flex;flex-direction:column;align-items:center}'+
 '.cert .cnw{position:relative;display:inline-block;padding:3mm 4mm 1mm;border-bottom:.5mm solid var(--c);min-width:44mm}.cert .cnw b{position:relative;font-family:Tajawal,"IBM Plex Sans Arabic",sans-serif;font-size:13pt;font-weight:800;color:#2A2A2E;z-index:1}.cert .cnw img{position:absolute;left:50%;top:50%;transform:translate(-50%,-55%);height:24mm;max-width:60mm;object-fit:contain;opacity:.62;mix-blend-mode:multiply;z-index:2;pointer-events:none}.cert .cr{font-family:Tajawal,"IBM Plex Sans Arabic",sans-serif;font-size:10pt;color:#6B6B72;margin-top:1mm}'+
 '.cert.po h1{font-size:46pt}.cert.po.ts-serif h1{font-size:50pt}.cert.po.ts-ruqaa h1{font-size:52pt}.cert.po .nm{font-size:32pt}.cert.po .rs{font-size:13pt}.cert.po .sgs{grid-template-columns:1fr 24mm 1fr}.cert.po .cnw{min-width:38mm}.cert.po .ch{margin-bottom:4mm}.cert h1,.cert .t2,.cert .ld,.cert .nm,.cert .mt,.cert .rs,.cert .cnw b,.cert .cr,.cert .ph,.cert .dt{font-family:Marhey,"IBM Plex Sans Arabic",sans-serif!important}.cert h1{font-weight:700!important;letter-spacing:0!important}.cert .nm{font-weight:600!important}.cert .t2{font-weight:600}.cert .rs{font-weight:400}.cert .cnw b{font-size:16pt!important;z-index:3!important}.cert.po .cnw b{font-size:15pt!important}.cert .cnw img{transform:translate(-50%,-44%)!important;height:28mm!important;max-width:68mm!important;z-index:2}.cert .ch{gap:2.5mm}.cert .vs{margin-top:.5mm}.cert .ms{margin:3mm 0 3mm}.cert .t2{margin:1.5mm 0 4mm}.cert .ld{margin:0 0 1.5mm}.cert .orn{margin:0 0 2.5mm}.cert .mt{margin:0 0 2.5mm}.cert .sgs{margin-top:3mm}.cert.po .ch{gap:4mm}.cert.po .ms{margin:6mm 0 5mm}.cert.po .t2{margin:2.5mm 0 7mm}.cert.po .ld{margin:0 0 3mm}.cert.po .orn{margin:1mm 0 4mm}.cert.po .mt{margin:0 0 4mm}.cert.po .rs{line-height:2}.cert.po .sgs{margin-top:6mm}';

